def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")

    process = subprocess.Popen(f"bash {script_path}", shell=True)
    ps_process = psutil.Process(process.pid)

    accumulated_cpu = 0.0
    accumulated_memory = 0
    start_time = time.time()

    try:
        while process.poll() is None:
            if (time.time() - start_time) > timeout:
                break

            try:
                cpu_usage = ps_process.cpu_percent(interval=None)
                mem_usage = ps_process.memory_info().rss
                accumulated_cpu += cpu_usage
                accumulated_memory += mem_usage
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                break

            time.sleep(0.1)
    finally:
        if process.poll() is None:
            process.terminate()
            process.wait()

    return {
        'CPU Usage': accumulated_cpu,
        'Memory Usage': accumulated_memory
    }

